from itertools import product

def is_kawaii(sequence):
    N = len(sequence)
    # Determine the maximum element M
    if not sequence:
        return True # Vacuously true for empty sequence
    M = max(sequence)

    # Check conditions for k = 2 up to M
    for k in range(2, M + 1):
        # Condition 1: If k appears, k-1 must appear
        if k in sequence:
            if (k - 1) not in sequence:
                return False

            # Condition 2: First occurrence of k-1 must come before last occurrence of k

            # Find F(k-1): index of first occurrence of k-1
            try:
                F_k_minus_1 = sequence.index(k - 1)
            except ValueError:
                # Should not happen if we passed Condition 1 check, but defensive coding
                return False 

            # Find L(k): index of last occurrence of k
            # sequence.rindex(k) finds the index of the last occurrence
            try:
                L_k = sequence.rindex(k)
            except ValueError:
                # Should not happen if k in sequence
                return False

            if F_k_minus_1 >= L_k:
                return False

    return True

