from itertools import product

def find_first_index(sequence, value):
    """Returns the index of the first occurrence of value."""
    try:
        return sequence.index(value)
    except ValueError:
        return -1 # Not found

def find_last_index(sequence, value):
    """Returns the index of the last occurrence of value."""
    for i in range(len(sequence) - 1, -1, -1):
        if sequence[i] == value:
            return i
    return -1 # Not found

def is_kawaii(sequence):
    if not sequence:
        return True 
    M = max(sequence)

    # Check conditions for k = 2 up to M
    for k in range(2, M + 1):
        # Check if k is present
        if k in sequence:
            # Condition 1: k-1 must appear
            if (k - 1) not in sequence:
                return False

            # Condition 2: First occurrence of k-1 must come before last occurrence of k

            # F(k-1)
            F_k_minus_1 = find_first_index(sequence, k - 1)

            # L(k)
            L_k = find_last_index(sequence, k)

            # Since we checked k in sequence and k-1 in sequence, these indices should be >= 0

            if F_k_minus_1 >= L_k:
                return False

    return True

